import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    abbreviations = input_data[1:]

    used_suffixes = set()
    current_year = 1989

    for abbr in abbreviations:
        suffix = abbr[4:]

        candidate = int(suffix)
        if candidate < 1989:
            candidate += 10 ** len(suffix)

        if candidate < 1989:
            while candidate < 1989:
                candidate += 10 ** len(suffix)

        if candidate > 9999:
            print(candidate)
            continue

        while True:
            test_suffix = str(candidate)[-len(suffix):]
            if test_suffix == suffix and candidate not in used_suffixes:
                break
            candidate += 10 ** len(suffix)
            if candidate > 9999:
                break

        if candidate <= 9999:
            used_suffixes.add(candidate)
            print(candidate)
